mapper.select:
SELECT COUNT(1)
FROM care_plan_task_checkin
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND checkin_date = #{day}
  AND status = 'DONE'
  AND recorded_by_staff_id IS NULL
  AND gmt_created < #{before}
  AND is_deleted = 0

SELECT COUNT(DISTINCT COALESCE(group_id, DATE_FORMAT(recorded_at, '%Y%m%d%H%i')))
FROM vital_record
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND recorded_at >= #{from}
  AND recorded_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
  AND source <> 'STAFF'
  AND recorded_by_staff_id IS NULL
  AND is_deleted = 0

SELECT COUNT(1)
FROM diet_meal
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND meal_date BETWEEN #{from} AND #{to}
  AND source = 'PHOTO_AI'
  AND recorded_by_staff_id IS NULL
  AND is_deleted = 0

SELECT m.people_id
FROM people_org_membership m
INNER JOIN reward_summary s
    ON s.people_id = m.people_id AND s.is_deleted = 0
   AND s.reward_disabled = 0 AND IFNULL(s.peer_opt_out, 0) = 0
WHERE m.tenant_id = #{tenantId}
  AND m.org_id = #{orgId}
  AND m.status = 'ACTIVE'
  AND m.is_deleted = 0
  AND DATE(COALESCE(m.joined_at, m.gmt_created)) BETWEEN #{joinFrom} AND #{joinTo}
  AND m.people_id <> #{excludePeopleId}
